function computeMaytagDualEraResult(serialRaw, modelRaw) {
  var preDecoder = decoderData.appliances.decoders.maytag_pre_2006;
  var postDecoder = decoderData.appliances.decoders.maytag_post_2006;
  var preRaw = null, postRaw = null;
  try { preRaw = preDecoder.decode(serialRaw, modelRaw); } catch (err) { preRaw = null; }
  try { postRaw = postDecoder.decode(serialRaw, modelRaw); } catch (err) { postRaw = null; }

  var preYear = preRaw && preRaw.year ? filterYearsByEra(String(preRaw.year), "pre") : null;
  var postYear = postRaw && postRaw.year ? filterYearsByEra(String(postRaw.year), "post") : null;
  var preValid = !!(preRaw && preYear && sanitizeDecodeResult({ year: preYear }).valid);
  var postValid = !!(postRaw && postYear && sanitizeDecodeResult({ year: postYear }).valid);

  if (!preValid && !postValid) {
    return {
      supported: false,
      preValid: false,
      postValid: false,
      reason: "Neither the Maytag pre-2006 nor post-2006 serial format matched this serial number."
    };
  }

  var combinedYears = [];
  if (preValid) combinedYears = combinedYears.concat(parseCandidateYears(preYear));
  if (postValid) combinedYears = combinedYears.concat(parseCandidateYears(postYear));
  var seenYears = {};
  combinedYears = combinedYears.filter(function (year) {
    if (seenYears[year]) return false;
    seenYears[year] = true;
    return true;
  }).sort(function (a, b) { return a - b; });
  var combinedYearDisplay = combinedYears.join("/");

  var combinedMonth;
  if (preValid && postValid) {
    combinedMonth = preRaw.month === postRaw.month ? preRaw.month : "Depends on era — see notes below";
  } else if (preValid) {
    combinedMonth = preRaw.month;
  } else {
    combinedMonth = postRaw.month;
  }

  var noteParts = [];
  if (preValid) noteParts.push("Maytag pre-2006 style: " + preYear + " (" + (preRaw.month || "N/A") + ").");
  else noteParts.push("Maytag pre-2006 style did not match this serial number.");
  if (postValid) noteParts.push("Maytag post-2006 style: " + postYear + " (" + (postRaw.month || "N/A") + ").");
  else noteParts.push("Maytag post-2006 style did not match this serial number.");
  if (preValid && postValid) {
    noteParts.push("The correct result depends on whether this unit was made before or after Whirlpool's post-2006 change to Maytag's serial format. Add a model number if you'd like help narrowing it.");
  }

  return {
    supported: true,
    preValid: preValid,
    postValid: postValid,
    preRaw: preRaw,
    postRaw: postRaw,
    preYear: preYear,
    postYear: postYear,
    combinedYears: combinedYears,
    combinedYearDisplay: combinedYearDisplay,
    combinedMonth: combinedMonth,
    notesText: noteParts.join(" ")
  };
}

function decodeMaytagBothEras(serialRaw, modelRaw, brandId, analyticsAttempt) {
  analyticsAttempt=analyticsAttempt||beginDecodeLifecycle("Maytag",currentCategory||"appliances");
  clearSupplementalModelError();
  updateSearchQueryLine();
  document.getElementById("serialResults").classList.add("hidden");
  var ageResultsEl = document.getElementById("ageResults");
  ageResultsEl && ageResultsEl.classList.add("hidden");
  var moreOptionsBodyEl = document.getElementById("moreOptionsBody");
  moreOptionsBodyEl && moreOptionsBodyEl.classList.add("hidden");
  var moreOptionsArrowEl = document.getElementById("moreOptionsArrow");
  moreOptionsArrowEl && moreOptionsArrowEl.classList.remove("open");
  ["replacements", "specs", "market"].forEach(function (key) {
    var el = document.getElementById("ai-result-" + key);
    if (el) { el.classList.add("hidden"); el.textContent = ""; }
  });
  setLoadingActive();
  setTimeout(function () {
    var result = computeMaytagDualEraResult(serialRaw, modelRaw);

    if (!result.supported) {
      completeDecodeLifecycle(analyticsAttempt,{result_status:"unsupported",result_precision:"none",date_precision:"none",candidate_year_count:0,ambiguous:false,refinement_used:false,evidence_type:"serial-rule"});
      showDecodeFallback(
        { name: "Maytag", method: "Maytag pre/post-2006 combined check" },
        serialRaw,
        brandId,
        result.reason
      );
      return;
    }

    document.getElementById("resultYear").textContent = result.combinedYearDisplay;
    document.getElementById("resultMonth").textContent = result.combinedMonth;
    document.getElementById("resultBrand").textContent = "Maytag";
    document.getElementById("resultMethod").textContent = "Maytag pre/post-2006 combined check";
    document.getElementById("resultNotes").textContent = sanitizeAlertText(result.notesText);
    updateResultWarning({ year: result.combinedYearDisplay, month: result.combinedMonth }, brandId);
    setEstimatedAgeVisibility(hasSingleResolvedYear(result.combinedYearDisplay), computeEstimatedAge(result.combinedYearDisplay));

    var refinementPanel = ensureRefinementPanel();
    if (refinementPanel) refinementPanel.classList.add("hidden");

    renderUpsellCard(result.combinedYears.length > 1 ? "ambiguous" : "resolved", {
      brand: "Maytag",
      model: modelRaw,
      category: currentCategory,
      resultId: generateDecodeResultId()
    });

    showBrandLogo("serialBrandLogo", brandId, "Maytag");
    currentFeedbackContext = { brand: "Maytag", serial: serialRaw };
    lastSerialResolutionState = {
      brandId: brandId,
      decoderName: "Maytag",
      serial: serialRaw,
      model: modelRaw,
      rawResult: { year: result.combinedYearDisplay, month: result.combinedMonth, notes: result.notesText },
      candidates: result.combinedYears.slice(),
      chosenYear: null,
      summary: "",
      baseNotes: result.notesText,
      refinementModel: "",
      refinementContext: ""
    };

    completeDecodeLifecycle(analyticsAttempt,{
      result_status:result.combinedYears.length>1?"ambiguous":"resolved",
      result_precision:result.combinedYears.length>1?"candidate-years":"year-month",
      date_precision:result.combinedYears.length>1?"multiple-candidates":"month-year",
      candidate_year_count:result.combinedYears.length,
      ambiguous:result.combinedYears.length>1,
      refinement_used:false,
      evidence_type:"serial-rule"
    });

    setLoadingSuccess(function () {
      document.getElementById("serialResults").classList.remove("hidden");
      document.getElementById("serialResults").scrollIntoView({ behavior: "smooth", block: "nearest" });
    });
  }, 1400);
}
